(() => {
  "use strict";
  const clips = Object.freeze({"airhorn":"","applause":"","rimshot":"","ding":"","boo":"","eggs":"","tomato":"","scratch":"","buzzer":"","laugh":"","cash":"","quack":"","crickets":"","trombone":"","boom":""});
  function bytes(id) {
    if (typeof id !== "string" || !Object.hasOwn(clips, id)) throw new Error("That sound is not available.");
    return Uint8Array.from(atob(clips[id]), (character) => character.charCodeAt(0)).buffer;
  }
  globalThis.MeetSoundboardAudio = Object.freeze({ bytes });
})();
